  blackSea: [[27.5, 42.5], [28, 44.5], [30, 46], [33, 46], [35, 45.3], [37, 45.3], [38.5, 44.5], [41.5, 41.5], [38, 41], [35, 42], [32, 41.8], [29, 41.2]],
