export const FILTERS = [
  ["all", "Все"], ["economic", "Прогнозы"], ["conflict", "Конфликты"], ["disaster", "Катастрофы"],
  ["economy", "Экономика"], ["politics", "Политика"], ["tech", "Технологии"],
];

/** Подходит ли новость под фильтр (катастрофы — и землетрясения; экономика — и энергетика). */
export function matches(item, filter) {
  if (filter === "all") return true;
  if (filter === "economic") return item.economic;
  if (filter === "disaster") return item.kind === "disaster" || item.kind === "quake";
  if (filter === "economy") return item.kind === "economy" || item.kind === "energy";
  return item.kind === filter;
}

/** «5 мин назад», «2 ч назад», «вчера» — по unix-времени. */
export function ago(ts, now = Date.now() / 1000) {
  const s = Math.max(0, now - ts);
  if (s < 90) return "только что";
  if (s < 3600) return `${Math.round(s / 60)} мин назад`;
  if (s < 86400) return `${Math.round(s / 3600)} ч назад`;
  return s < 172800 ? "вчера" : `${Math.round(s / 86400)} дн назад`;
}

export const arrow = (dir) => (dir > 0 ? "↑" : dir < 0 ? "↓" : "→");

/** Цвет давления на рынок: вверх — зелёный, вниз — малиновый, слабое — серый. */
export const pressureClass = (p) => (p >= 0.2 ? "up" : p <= -0.2 ? "down" : "flat");

/** Новые маркеры в начало, без повторов, не больше limit. */
export function mergeItems(old, fresh, limit = 400) {
  const seen = new Set(), out = [];
  for (const it of [...fresh, ...old]) {
    if (seen.has(it.id)) continue;
    seen.add(it.id);
    out.push(it);
  }
  return out.sort((a, b) => b.ts - a.ts).slice(0, limit);
}
